function fade(media,target,duration=420){if(!media)return;const old=fadeFrames.get(media);if(old)cancelAnimationFrame(old);const start=clamp(media.volume),end=clamp(target,0,.95),began=performance.now();if(end>0&&media.paused){media.muted=false;media.play().catch(()=>{})}const step=now=>{const q=clamp((now-began)/Math.max(1,duration)),smooth=q*q*(3-2*q);media.volume=start+(end-start)*smooth;if(q<1){const frame=requestAnimationFrame(step);fadeFrames.set(media,frame)}else{fadeFrames.delete(media);if(end===0)media.pause()}};const frame=requestAnimationFrame(step);fadeFrames.set(media,frame)}
