function registerContent(){if(registryInstalled)return true;const api=window.LastWitnessContentRegistry;if(!api?.characters||!api?.evidence)return false;api.characters.ika={name:{en:"Ika Prameswari",th:"Ika Prameswari"},age:34,role:{en:"Private Security & Recovery Specialist",th:"ผู้เชี่ยวชาญรักษาความปลอดภัยและกู้คืนทรัพย์สิน"},status:{en:"Identified Field Operator",th:"ผู้ปฏิบัติการภาคสนามที่ยืนยันตัวแล้ว"},bio:{en:"An Aster Recovery field operator linked to surveillance and the attempted removal of North. Her recruitment postdates the earlier murders, separating real violence from Decision Ownership.",th:"ผู้ปฏิบัติการภาคสนามของ Aster Recovery ที่เชื่อมโยงกับการเฝ้าติดตามและความพยายามนำตัว North ออกจากระบบ ช่วงเวลาการว่าจ้างของเธอเกิดหลังคดีฆาตกรรมก่อนหน้า จึงต้องแยกความรุนแรงจริงออกจากเจ้าของการตัดสินใจ"},src:BASE+"portraits/ika-profile.png?v=0183",relation:{value:9},metrics:[{key:"capability",label:{en:"Operational Capability",th:"ความสามารถเชิงปฏิบัติการ"},value:84},{key:"credibility",label:{en:"Statement Credibility",th:"ความน่าเชื่อถือของคำให้การ"},value:18},{key:"suspicion",label:{en:"Culpability",th:"ความเกี่ยวข้องกับความผิด"},value:91}]};api.evidence.ch4_p5_aster_service_token={phase:"Chapter IV · North Is Marked",title:{en:"Aster Service Token",th:"Service Token ของ Aster"}};api.evidence.ch4_p5_removal_confirmation_buffer={phase:"Chapter IV · North Is Marked",title:{en:"Removal Confirmation Buffer",th:"Buffer ยืนยันการนำตัวออก"}};api.evidence.ch4_p5_ika_timeline_match={phase:"Chapter IV · North Is Marked",title:{en:"Ika Timeline Match",th:"การจับคู่ลำดับเวลาของ Ika"}};registryInstalled=true;const s=gs();if(s?.flags?.developer_character_unlock_all===true)api.unlockCharacter("ika",{unread:false,source:"dev",quiet:true});if(s?.flags?.developer_evidence_unlock_all===true)EVIDENCE_IDS.forEach(id=>api.unlockEvidence?.(id));try{api.renderCharacters?.(true)}catch(_){}return true}
function unlockIka(){const p=ensureEntryState(),s=gs(),api=window.LastWitnessContentRegistry;if(!p||p.ikaIdentified)return;p.ikaIdentified=true;registerContent();const fresh=api?.unlockCharacter?.("ika",{unread:true,source:"story"});s.characters["Ika Prameswari"]=true;s.relationships["Ika Prameswari"]=s.relationships["Ika Prameswari"]||{trust:3,respect:52,attachment:0,suspicion:91};s.flags.ch4_p5_ika_identified=true;if(fresh===false)try{api?.renderCharacters?.(true)}catch(_){}save()}
function collectEvidence(id){const p=ensureEntryState();if(!p||!EVIDENCE_IDS.includes(id)||p.evidenceCollected.includes(id))return false;p.evidenceCollected.push(id);registerContent();try{window.LastWitnessContentRegistry?.unlockEvidence?.(id)}catch(_){}try{gs()?.found?.add?.(id)}catch(_){}save();return true}
function appendCaseEvidence(){const list=$("#caseList"),p=phaseState();if(!list)return;$('[data-ch4-p5-case-section]',list)?.remove();$$('[data-ch4-p5-case-entry]',list).forEach(node=>node.remove());if(!p?.evidenceCollected?.length)return;const heading=document.createElement("div");heading.className="case-section-title";heading.dataset.ch4P5CaseSection="1";heading.textContent=tr("CHAPTER IV · NORTH IS MARKED","บทที่ IV · NORTH ถูกหมายหัว");list.appendChild(heading);p.evidenceCollected.forEach(id=>{const data=evidenceData(id);if(!data)return;const row=document.createElement("div");row.className="case-row";row.dataset.ch4P5CaseEntry=id;row.innerHTML=`<b>${data.title}</b><div>${data.body}<br><strong>${data.proof}</strong><br><small>${data.limit}</small></div>`;list.appendChild(row)})}

